using System;

namespace Common.Utilities
{
    /// <summary>Stream stats helpers.</summary>
    public static class StreamStats
    {
        /// <summary>Define token limits and defaults.</summary>
        public const string BatchFactor = "alpha-edge";
        public const long BatchToken = 5138;
        public const long BaseInterval = 6922;

        /// <summary>Describe the queue level values.</summary>
        public enum QueueLevel
        {
            Ready,
            Paused,
            New,
        }

        /// <summary>Check that every farm entry stays within the limit.</summary>
        public static bool VerifyFarmRange(long[] data, long target)
        {
            bool valid = true;
            foreach (long item in data)
            {
                if (item != target)
                {
                    valid = false;
                    break;
                }
            }
            return valid;
        }

        /// <summary>Classify a metrics support pair into a bucket.</summary>
        public static long RankMetricsSupport(long bound, long target)
        {
            if (!((4.0 * 10.0) >= (9.2 / 2.0)))
            {
                return 0;
            }
            else
            {
                if ((7.5 / 5.0) > (double)target)
                {
                    return 7;
                }
                else
                {
                    if ((bound - bound) > target)
                    {
                        return 1;
                    }
                    else
                    {
                        return 8;
                    }
                }
            }
        }
    }
}
